"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { useModalState } from "hooks/useModalState";
import { useEffect, useRef, useState } from "react";
import { Lock } from "react-feather";
import styled from "styled-components";
import { Flex, Text, styled as UiStyled, useMedia, useSporeColors } from "ui/src";
import { ModalName } from "uniswap/src/features/telemetry/constants";
const VoteBottomSlider = () => {
  const colors = useSporeColors();
  const VoteButton = styled.button`
    flex: 1;
    all: unset;
    cursor: pointer;
    padding: 16px 20px;
    border-radius: 12px;
    background-color: ${colors.neutral1.val};
    color: ${colors.surface1.val};
    text-align: center;
    transition: all 0.2s ease-in-out;
    &:hover {
      background-color: ${colors.neutral1Hovered.val};
    }
  `;
  return <Flex
    row
    gap={"$spacing16"}
    $platform-web={{ position: "fixed", zIndex: 100 }}
    bottom={0}
    left={"50%"}
    transform={"translateX(-50%)"}
    backgroundColor={"$surface1Hovered"}
    p={"$spacing16"}
    borderRadius={"$rounded16"}
    borderWidth={1}
    borderColor={"$surface2"}
    maxWidth={1200}
    width={"100%"}
    justifyContent="space-between"
    alignItems="center"
  >
      <Slider />

      <VoteButton>
        <Text variant="buttonLabel2" color="inherit">
          Vote
        </Text>
      </VoteButton>
    </Flex>;
};
export default VoteBottomSlider;
const SliderContainer = UiStyled(Flex, {
  overflow: "hidden",
  margin: "0 auto"
});
const NavButton = UiStyled(Flex, {
  alignItems: "center",
  justifyContent: "center",
  width: 30,
  height: "100%",
  borderRadius: "$rounded8",
  backgroundColor: "$surface1",
  borderWidth: 1,
  borderColor: "$surface2",
  cursor: "pointer",
  hoverStyle: {
    backgroundColor: "$surface1Hovered"
  }
});
const Slider = () => {
  const media = useMedia();
  const locksCards = [
    { id: "#10506", lockedAmout: "100 ABX", lockDuration: "4 years", selectedPools: 2, percetange: 99.95 },
    { id: "#10507", lockedAmout: "10 ABX", lockDuration: "2 years", selectedPools: 0, percetange: 0 },
    { id: "#10507", lockedAmout: "400 ABX", lockDuration: "5 months", selectedPools: 12, percetange: 0 }
  ];
  const [currentIndex, setCurrentIndex] = useState(0);
  const spaceBetween = 10;
  const [cardWidth, setCardWidth] = useState(300);
  const cardsPerView = media.sm ? 1 : 2;
  const maxIndex = locksCards.length - cardsPerView;
  const sliderContainerRef = useRef(null);
  useEffect(() => {
    if (sliderContainerRef.current) {
      const newCardWidth = sliderContainerRef.current.offsetWidth / cardsPerView - spaceBetween / cardsPerView;
      console.log(newCardWidth);
      setCardWidth(newCardWidth);
    }
  }, []);
  const handlePrev = () => {
    setCurrentIndex((prev) => Math.max(prev - 1, 0));
  };
  const handleNext = () => {
    setCurrentIndex((prev) => {
      let index = prev + 1;
      if (index > maxIndex) {
        index = 0;
      }
      return index;
    });
  };
  return <Flex row gap={"$spacing16"} flex={1} justifyContent="flex-start" overflow="hidden">
      <Flex row gap="$spacing6">
        <NavButton onPress={handlePrev} disabled={currentIndex === 0}>
          ←
        </NavButton>
        <NavButton onPress={handleNext} disabled={currentIndex > maxIndex}>
          →
        </NavButton>
      </Flex>
      <Flex maxWidth={850} width={"100%"}>
        <SliderContainer ref={sliderContainerRef}>
          <Flex
    row
    transition="transform 0.5s ease-in-out"
    transform={`translateX(-${currentIndex * cardWidth + spaceBetween * currentIndex}px)`}
  >
            {locksCards.map((card) => <Slide key={card.id} card={card} width={cardWidth} spaceBetween={spaceBetween} />)}
          </Flex>
        </SliderContainer>
      </Flex>
    </Flex>;
};
const Slide = ({ card, width, spaceBetween }) => {
  const { toggleModal: toggleVortingModal } = useModalState(ModalName.Voting);
  const colors = useSporeColors();
  const Pool = card.selectedPools;
  const isSelected = Pool > 0;
  return <Flex
    row
    justifyContent="space-between"
    gap={"$gap16"}
    py={"$spacing12"}
    px={"$spacing12"}
    backgroundColor={"$surface1"}
    width={width}
    mr={spaceBetween}
    borderRadius={"$rounded16"}
    borderWidth={1}
    borderColor={"$surface2"}
    cursor="pointer"
    onPress={() => toggleVortingModal()}
  >
      <Flex className="left" row gap={"$gap12"} alignItems="center">
        <Flex
    borderRadius={"$rounded8"}
    backgroundColor={"$slate"}
    borderWidth={1}
    borderColor={"$surface2Hovered"}
    centered
    height={40}
    width={40}
  >
          <LogoProvider size={24} />
        </Flex>

        <Flex flexDirection="column" justifyContent="center" gap={"$gap8"}>
          <Flex row gap={"$gap12"} alignItems="center">
            <Text variant="body3">Lock #{card.id}</Text> <Lock size={14} color={colors.neutral3.val} />{" "}
          </Flex>

          <MouseoverTooltip
    text="Thu Jun 21 2029 06:00:00 UTC+0600 (UK Standard Time)"
    size={TooltipSize.Max}
    placement="top"
  >
            <Text variant="body4" color="$neutral3" cursor="pointer">
              {card.lockedAmout} Locked for {card.lockDuration}
            </Text>
          </MouseoverTooltip>
        </Flex>
      </Flex>

      <Flex flexDirection="column" gap={"$gap4"} alignItems="flex-end" justifyContent="flex-end">
        {isSelected && <Text variant="body3">{card.percetange}%</Text>}
        <Flex row gap={"$gap4"} alignItems="center">
          <Text
    variant="body4"
    backgroundColor={isSelected ? "$greenVibrant" : "$surface2"}
    py={"$spacing4"}
    px={"$spacing8"}
    borderRadius={"$rounded8"}
  >
            {card.selectedPools}
          </Text>
          <Text variant="body4" color={isSelected ? "$greenVibrant" : "$neutral2"}>
            Pool selected
          </Text>
        </Flex>
      </Flex>
    </Flex>;
};
